type LoadingState = { status: "loading" }
type SuccessState<T> = { status: "success"; data: T }
type ErrorState = { status: "error"; message: string }
type AsyncState<T> = LoadingState | SuccessState<T> | ErrorState

function render<T>(state: AsyncState<T>): string {
    switch (state.status) {
        case "loading": return "Yuklanmoqda..."
        case "success": return `Ma'lumot: ${JSON.stringify(state.data)}`
        case "error": return `Xato: ${state.message}`
    }
}

console.log(render({ status: "loading" }))
console.log(render({ status: "success", data: [1, 2, 3] }))
console.log(render({ status: "error", message: "Tarmoq yo'q" }))

