type State = { count: number; history: number[] }
type Action = { type: "add"; by: number } | { type: "undo" }
function reduce(s: State, a: Action): State {
    if (a.type === "add") return { count: s.count + a.by, history: [...s.history, s.count] }
    const prev = s.history.at(-1)
    return prev === undefined ? s : { count: prev, history: s.history.slice(0, -1) }
}
let st: State = { count: 0, history: [] }
for (const a of [{ type: "add", by: 5 }, { type: "add", by: 3 }, { type: "undo" }] as Action[]) st = reduce(st, a)
console.log(st)

