const cache: { [url: string]: { body: string; at: number } } = {}

function fetchCached(url: string) {
    if (cache[url]) return `kesh: ${cache[url].body}`
    cache[url] = { body: `javob(${url})`, at: Object.keys(cache).length }
    return `yangi: ${cache[url].body}`
}

console.log(fetchCached("/a"), "|", fetchCached("/a"), "|", fetchCached("/b"))

