type Entry = { value: string; expires: number }
const store: { [key: string]: Entry } = {}
const setItem = (k: string, v: string, ttl: number, now: number) => { store[k] = { value: v, expires: now + ttl } }
const getItem = (k: string, now: number) => (store[k] && store[k].expires > now ? store[k].value : null)
